function csvParse(t){const rows=[];let r=[],c='',q=false;const d=(t.split('\n')[0].match(/;/g)||[]).length>(t.split('\n')[0].match(/,/g)||[]).length?';':',';
 for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch=='"'&&t[i+1]=='"'){c+='"';i++}else if(ch=='"')q=false;else c+=ch}else if(ch=='"')q=true;else if(ch==d){r.push(c);c=''}else if(ch=='\n'){r.push(c);rows.push(r);r=[];c=''}else if(ch!='\r')c+=ch}
 if(c||r.length){r.push(c);rows.push(r)}return rows.filter(x=>x.some(y=>y.trim()))}
const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z ]/g,'').trim();
function dlg(html){return new Promise(res=>{const o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg" role="dialog" aria-modal="true">'+html+'</div>';document.body.appendChild(o);const i=o.querySelector('input');const done=v=>{o.remove();res(v)};
 o.addEventListener('click',e=>{const b=e.target.closest('[data-r]');if(b)done(b.dataset.r==='1'?(i?i.value:true):null);else if(e.target===o)done(null)});if(i){i.focus();i.addEventListener('keydown',e=>{if(e.key==='Enter')done(i.value)})}})}
const ask=async(t,m,ok='Aceptar',danger=false)=>!!(await dlg(`<h2>${t}</h2><p class="mut">${m}</p><div class="row"><button class="sec full" data-r="0">Cancelar</button><button class="full ${danger?'dng':'pri'}" data-r="1">${ok}</button></div>`));
const askText=(t,lb,ph,type='text')=>dlg(`<h2>${t}</h2><label style="margin-top:10px">${lb}</label><input type="${type}" placeholder="${ph}" autocomplete="off"><div class="row"><button class="sec full" data-r="0">Omitir</button><button class="full pri" data-r="1">Guardar</button></div>`);

const normH=s=>String(s??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z ]/g,' ').replace(/\s+/g,' ').trim();
const cap=s=>s.replace(/\S+/g,w=>w[0].toUpperCase()+w.slice(1).toLowerCase());
const cell=v=>{if(v==null)return '';if(typeof v==='number')return Number.isInteger(v)?String(v):String(+v.toFixed(6));if(v instanceof Date)return v.toISOString().slice(0,10);return String(v).trim()};
const num=v=>{if(v==null||v==='')return '';if(typeof v==='number')return String(v);let s=String(v).replace(/[^\d.,-]/g,'');if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(s))s=s.replace(/\./g,'');return s};
const serial=n=>new Date(Date.UTC(1899,11,30)+Math.round(n)*864e5).toISOString().slice(0,10);
const toISO=v=>{if(v===''||v==null)return '';if(v instanceof Date)return new Date(v.getTime()-v.getTimezoneOffset()*6e4).toISOString().slice(0,10);if(typeof v==='number')return v>20000&&v<80000?serial(v):'';const s=String(v).trim();let m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})/);if(m)return `${m[3].length==2?'20'+m[3]:m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;return ''};
const pct=v=>{if(v===''||v==null)return '';if(typeof v==='number')return String(+(v<=1?v*100:v).toFixed(2));const n=parseFloat(String(v).replace('%','').replace(',','.'));if(isNaN(n))return '';return String(String(v).includes('%')||n>1?n:+(n*100).toFixed(2))};
const fdate=s=>{const m=String(s||'').match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return s||'';const a=Math.floor((Date.now()-new Date(+m[1],m[2]-1,+m[3]))/31557600000);return `${m[3]}/${m[2]}/${m[1]}`+(a>0?` · ${a} año${a>1?'s':''}`:'')};
const COLS=[['num',['legajo','numero','nro']],['dni',['dni','documento']],['apellido',['apellido']],['nombre',['nombre completo','nombre y apellido','nombre']],['cobra',['cobro','cobra','sueldo','monto']],['extra',['extra','adicional']],['ingreso',['fecha de ingreso','ingreso','alta']],['aCargo',['persona a cargo','a cargo']],['telACargo',['telefono a cargo','tel a cargo','telefono persona']],['tel',['telefono','tel','celular','contacto']],['estado',['estado']]];
const hit=(h,n)=>n.length<=4?(' '+h+' ').includes(' '+n+' ')||h.replace(/ /g,'')===n:h.includes(n);
function mapHeaders(H){const m={},used=new Set();for(const [k,ns] of COLS){for(const n of ns){const i=H.findIndex((h,j)=>!used.has(j)&&h&&hit(h,n));if(i>=0){m[k]=i;used.add(i);break}}}return m}
function procSheet(R,st){R=R.filter(r=>r.some(c=>cell(c)!==''));let hi=-1,m;
 for(let i=0;i<Math.min(R.length,10);i++){const mm=mapHeaders(R[i].map(normH));if(Object.keys(mm).length>=2&&(mm.num!=null||mm.nombre!=null||mm.dni!=null)){hi=i;m=mm;break}}
 if(hi<0)return false;if(m.tel!=null){if(m.aCargo!=null&&m.telACargo==null)m.telACargo=m.tel;else m.contacto=m.tel}
 const hdr=R[hi].map(x=>String(x??'').trim()),known=new Set(Object.values(m)),g=(x,k)=>m[k]==null?'':x[m[k]];
 R.slice(hi+1).forEach(x=>{if(!x.some(c=>cell(c)!==''))return;
  const o={num:cell(g(x,'num')),dni:cell(g(x,'dni')),nombre:cap(cell(g(x,'nombre'))),apellido:cap(cell(g(x,'apellido'))),cobra:num(g(x,'cobra')),extra:pct(g(x,'extra')),ingreso:toISO(g(x,'ingreso')),aCargo:cap(cell(g(x,'aCargo'))),telACargo:cell(g(x,'telACargo')),contacto:cell(g(x,'contacto'))};
  const e0=cell(g(x,'estado'));o.estado=['Activo','Pendiente','Inactivo'].find(s=>s.toLowerCase()===e0.toLowerCase())||'';
  const otros={};hdr.forEach((h,j)=>{if(!h||known.has(j))return;const v=x[j];if(cell(v)==='')return;otros[h]=(typeof v==='number'&&v>20000&&v<80000&&/fecha|ingreso|alta|nac|venc/i.test(h))?serial(v).split('-').reverse().join('/'):cell(v)});
  if(!o.num&&!o.nombre&&!o.dni){st.sk++;return}
  const mio=l=>!SRV||l.owner===S.me.user,ex=(o.num&&S.legs.find(l=>l.num===o.num&&mio(l)))||(o.dni&&S.legs.find(l=>l.dni===o.dni&&mio(l)))||null;
  if(ex){Object.keys(o).forEach(k=>{if(o[k]!=='')ex[k]=o[k]});ex.otros={...(ex.otros||{}),...otros};st.up++}else{S.legs.push({id:uid(),recibos:[],docs:[],...o,otros,estado:o.estado||'Activo'});st.nu++}});
 return true}
async function importSheets(sheets){const st={nu:0,up:0,sk:0,h:0};sheets.forEach(R=>{if(procSheet(R,st))st.h++});
 if(!st.h)return toast('No encontré las columnas (legajo, dni, nombre…) en el archivo');
 save();await dlg(`<h2>Importación lista</h2><p class="mut">${st.nu} legajos nuevos · ${st.up} actualizados${st.sk?' · '+st.sk+' filas sin datos omitidas':''}.<br>Total en la app: <b>${S.legs.length}</b> legajos.</p><div class="row"><button class="full pri" data-r="1">Ver legajos</button></div>`);go('home')}
async function loadXLSX(){if(typeof XLSX!=='undefined')return true;for(const src of ['lib/xlsx.full.min.js','https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js']){await new Promise(r=>{const s=document.createElement('script');s.src=src;s.onload=r;s.onerror=r;document.head.appendChild(s)});if(typeof XLSX!=='undefined')return true}return false}
const NATIVE=()=>!!(window.Capacitor&&Capacitor.isNativePlatform&&Capacitor.isNativePlatform()),PL=n=>window.Capacitor&&Capacitor.Plugins&&Capacitor.Plugins[n];
const b64=bl=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(bl)});
async function nativeSave(name,bl){const F=PL('Filesystem'),Sh=PL('Share');if(!F||!Sh)throw new Error('falta el complemento de archivos');const r=await F.writeFile({path:name,data:await b64(bl),directory:'CACHE'});await Sh.share({title:name,url:r.uri,dialogTitle:name})}
async function readFile(f){const n=f.name.toLowerCase(),o=$('#imp');if(o)o.textContent='Leyendo '+f.name+'…';
 try{if(n.endsWith('.csv')||n.endsWith('.txt'))return await importSheets([csvParse((await f.text()).replace(/^\uFEFF/,''))]);
  if(!(await loadXLSX()))return toast('No cargó el lector de Excel. Revisá la conexión o usá un CSV');
  const wb=XLSX.read(await f.arrayBuffer(),{type:'array'});await importSheets(wb.SheetNames.map(s=>XLSX.utils.sheet_to_json(wb.Sheets[s],{header:1,raw:true,defval:''})))}
 catch(e){toast('No se pudo leer el archivo')}if(o)o.textContent=''}
const idb=()=>new Promise((res,rej)=>{const r=indexedDB.open('lega_files',1);r.onupgradeneeded=()=>r.result.createObjectStore('f');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
async function fio(mode,fn){const d=await idb();return new Promise((res,rej)=>{const t=d.transaction('f',mode),q=fn(t.objectStore('f'));t.oncomplete=()=>res(q&&q.result);t.onerror=()=>rej(t.error)})}
const fput=(id,b,para)=>SRV?fetch(api('file/'+id+(para&&S.me&&para!==S.me.user?'?para='+encodeURIComponent(para):'')),{method:'POST',headers:hdr({'Content-Type':b.type||'application/octet-stream'}),body:b}).then(r=>{if(!r.ok)throw new Error('no')}):fio('readwrite',o=>o.put(b,id)),fget=id=>SRV?fetch(api('file/'+id),{headers:hdr()}).then(r=>r.ok?r.blob():null):fio('readonly',o=>o.get(id)),fdel=id=>SRV?fetch(api('file/'+id),{method:'DELETE',headers:hdr()}).catch(()=>{}):fio('readwrite',o=>o.delete(id));
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);

app.addEventListener('input',e=>{if(e.target.id==='q'){S.q=e.target.value;const q=S.q.toLowerCase().trim();const list=q?VL().filter(l=>[l.num,l.nombre,l.apellido,l.dni,l.owner].join(' ').toLowerCase().includes(q)):VL().slice().reverse();$('#res').innerHTML=listHTML(list,q)}});
app.addEventListener('change',async e=>{if(e.target.id==='ownf'){S.ownerF=e.target.value;return render()}if(e.target.id==='docf'&&e.target.files[0]){const fl=e.target.files[0],l=S.legs.find(x=>x.id===S.cur);if(fl.size>15*1024*1024){e.target.value='';return toast('El archivo supera los 15 MB')}
 const nota=((await askText('Documento cargado','Nota (opcional)','Ej: sueldo octubre'))||'').trim();const id=uid();
 try{await fput(id,fl,l.owner)}catch(er){return toast('No se pudo guardar el archivo en este navegador')}
 l.docs=l.docs||[];l.docs.push({id,kind:S.kind,name:fl.name,type:fl.type,size:fl.size,nota,fecha:new Date().toLocaleDateString('es-AR')});save();toast(S.kind+' guardado');return render()}
 
if(e.target.id==='file'&&e.target.files[0]){const f=e.target.files[0];e.target.value='';readFile(f)}});
app.addEventListener('keydown',e=>{if(e.key==='Enter'&&S.view==='login')act('login')});
app.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(b){e.preventDefault();act(b.dataset.a,b.dataset)}});

async function act(a,d={}){const v=id=>($('#'+id)||{}).value||'';
 if(a==='login'){if(SRV)return srvLogin(v('u').trim().toLowerCase(),v('p'));const u=S.users.find(x=>x.user===v('u').trim().toLowerCase());const h=await hash(v('p'));if(!u||u.pass!==h)return toast('Usuario o contraseña incorrectos');if(u.pend)return toast('Tu cuenta todavía no fue aprobada por el administrador');if(!u.activo)return toast('Tu usuario está pausado');S.me=u;try{sessionStorage.setItem('lega_me',u.user)}catch(e){}return go('home')}
 if(a==='wipe'){if(!(await ask('Borrar todos los legajos','Se eliminan TODOS TUS legajos con sus cobros y documentos. No se puede deshacer.','Borrar todo',true)))return;for(const l of S.legs.filter(q=>!SRV||q.owner===S.me.user))for(const x of (l.docs||[])){try{await fdel(x.id)}catch(e){}}S.legs=S.legs.filter(q=>SRV&&q.owner!==S.me.user);save();toast('Se borraron todos los legajos');return go('home')}
 if(a==='demo'){const N=['Elías Romero','Marta López','Christian Díaz','Lucía Fernández','Benjamín Ortiz','Rodrigo Suárez','Camila Acosta','Nicolás Herrera','Valentina Molina','Matías Ríos','Florencia Castro','Sebastián Vega','Julieta Peralta','Franco Giménez'],now=new Date(),hoy=now.toLocaleDateString('es-AR');
 for(let i=0;i<N.length;i++){const [nom,ap]=N[i].split(' '),cobra=420000+((i*7919)%14)*95000,rec=[],docs=[];
  for(let k=5;k>=0;k--){const dt=new Date(now.getFullYear(),now.getMonth()-k,1);rec.push({id:uid(),mes:dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0'),monto:String(Math.round(cobra*(0.93+((i+k)%5)*0.025))),nota:''})}
  const addDoc=async(kind,name)=>{const id=uid();try{await fput(id,new Blob(['Documento de ejemplo'],{type:'text/plain'}))}catch(e){}docs.push({id,kind,name,type:'text/plain',size:20,nota:'',fecha:hoy})};
  if(i%3!==1)await addDoc('Declaración jurada','declaracion-jurada.txt');if(i%2===0)await addDoc('Recibo','recibo-del-mes.txt');
  S.legs.push({id:uid(),demo:true,num:String(41200+i*137),dni:String(27000000+i*1234567),nombre:nom,apellido:ap,contacto:'11'+String(40000000+i*913377).slice(0,8),cobra:String(cobra),extra:String([10,15,20,25,30,35,40][i%7]),ingreso:(2008+(i*5)%17)+'-'+String(1+(i*7)%12).padStart(2,'0')+'-'+String(1+(i*11)%28).padStart(2,'0'),aCargo:i%4===0?'':N[(i+3)%N.length],telACargo:i%4===0?'':'11'+String(50000000+i*777331).slice(0,8),estado:i%7===3?'Pendiente':i%9===5?'Inactivo':'Activo',recibos:rec,docs,otros:{}})}
 save();toast('Datos de ejemplo cargados');return go('home')}
 if(a==='undemo'){for(const l of S.legs.filter(x=>x.demo))for(const x of (l.docs||[])){try{await fdel(x.id)}catch(e){}}S.legs=S.legs.filter(x=>!x.demo);save();toast('Ejemplo quitado');return go('home')}
 if(a==='srv'){const u=await askText('Servidor de LEGA','Dirección del servidor (vacío = modo local)','http://192.168.1.20:8080');if(u===null)return;let x=u.trim();if(x&&!/^https?:\/\//.test(x))x='http://'+x;x=x.replace(/\/+$/,'');try{if(x)localStorage.setItem('lega_server',x);else localStorage.removeItem('lega_server')}catch(e){}location.reload();return}
 if(a==='eye'){const p=$('#p');p.type=p.type==='password'?'text':'password';return}
 if(a==='logout'){if(SRV)await srvLogout();S.me=null;try{sessionStorage.removeItem('lega_me')}catch(e){}return go('login')}
 if(a==='go')return go(d.v);
 if(a==='open')return go('legajo',d.id);
 if(a==='new'){S.form={estado:'Activo',owner:S.me.user};return go('form')}
 if(a==='edit'){S.form={...S.legs.find(x=>x.id===d.id)};return go('form')}
 if(a==='savef'){const f={...S.form};['num','nombre','apellido','dni','contacto','cobra','extra','ingreso','aCargo','telACargo','estado'].forEach(k=>f[k]=v('f_'+k).trim());
  if(SRV&&isAdmin()&&$('#f_owner'))f.owner=v('f_owner');if(!f.nombre&&!f.apellido)return toast('Ingresá al menos nombre o apellido');
  if(f.num&&S.legs.some(x=>x.num===f.num&&x.id!==f.id&&(x.owner||'')===(f.owner||'')))return toast('Ya existe un legajo con ese número');
  if(f.id){S.legs=S.legs.map(x=>x.id===f.id?f:x)}else{f.id=uid();f.recibos=[];S.legs.push(f)}save();toast('Legajo guardado');return go('legajo',f.id)}
 if(a==='delleg'){if(!(await ask('Eliminar legajo','Se borra el legajo con sus cobros y documentos. No se puede deshacer.','Eliminar',true)))return;const L0=S.legs.find(x=>x.id===d.id);for(const x of (L0.docs||[])){try{await fdel(x.id)}catch(e){}}S.legs=S.legs.filter(x=>x.id!==d.id);save();return go('home')}
 if(a==='pick'){S.kind=d.k;return $('#docf').click()}
 if(a==='opendoc'){try{if(NATIVE()&&SRV&&BASE&&PL('Browser')){await PL('Browser').open({url:BASE+'/api/file/'+d.id+'?token='+encodeURIComponent(TOK)});return}const b=await fget(d.id);if(!b)return toast('No se encontró el archivo');if(NATIVE()){await nativeSave(S.legs.find(x=>x.id===S.cur).docs.find(x=>x.id===d.id).name,b);return}const u=URL.createObjectURL(b);const w=window.open(u,'_blank');if(!w){const a2=document.createElement('a');a2.href=u;a2.download=S.legs.find(x=>x.id===S.cur).docs.find(x=>x.id===d.id).name;a2.click()}}catch(e){toast('No se pudo abrir el archivo')}return}
 if(a==='deldoc'){if(!(await ask('Quitar documento','¿Querés quitar este documento del legajo?','Quitar',true)))return;const l=S.legs.find(x=>x.id===S.cur);try{await fdel(d.id)}catch(e){}l.docs=l.docs.filter(x=>x.id!==d.id);save();return render()}
 
if(a==='addmes'){const l=S.legs.find(x=>x.id===S.cur);if(!v('rm')||!v('rn'))return toast('Completá mes y monto');l.recibos=l.recibos||[];l.recibos.push({id:uid(),mes:v('rm'),monto:v('rn'),nota:v('rt').trim()});save();toast('Mes guardado');return render()}
 if(a==='delrec'){const l=S.legs.find(x=>x.id===S.cur);l.recibos=l.recibos.filter(x=>x.id!==d.id);save();return render()}
 if(a==='filt'){S.filt=d.v;return render()}
 if(a==='doreg'){const u=v('ru').trim().toLowerCase();if(!/^[a-z0-9._-]{3,}$/.test(u))return toast('Usuario: mínimo 3 caracteres, solo letras, números, punto o guion');if(v('rp').length<4)return toast('La contraseña debe tener al menos 4 caracteres');if(v('rp')!==v('rp2'))return toast('Las contraseñas no coinciden');if(SRV){try{await srvReg(u,v('rn1').trim(),await hash(v('rp')))}catch(e){return toast(e.message)}toast('Solicitud enviada. Esperá la aprobación del administrador');return go('login')}if(S.users.some(x=>x.user===u))return toast('Ese usuario ya existe, elegí otro');
  S.users.push({user:u,nombre:v('rn1').trim(),pass:await hash(v('rp')),rol:'viewer',activo:false,pend:true});save();toast('Solicitud enviada. Esperá la aprobación del administrador');return go('login')}
 if(a==='aprobar'){if(SRV)return uop('approve',{user:d.id,rol:v('pr_'+d.id)||'viewer'},'Acceso otorgado a '+d.id);const u=S.users.find(x=>x.user===d.id);u.rol=v('pr_'+d.id)||'viewer';u.pend=false;u.activo=true;save();toast('Acceso otorgado a '+u.user);return render()}
 if(a==='rechazar'){if(!(await ask('Rechazar solicitud','Se elimina la solicitud de '+d.id+'.','Rechazar',true)))return;if(SRV)return uop('reject',{user:d.id});S.users=S.users.filter(x=>x.user!==d.id);save();return render()}
 if(a==='uadd'){const u=v('nu').trim().toLowerCase();if(!/^[a-z0-9._-]{3,}$/.test(u))return toast('Usuario: mínimo 3 caracteres, solo letras, números, punto o guion');if(!u||!v('np'))return toast('Completá usuario y contraseña');if(SRV)return uop('create',{user:u,pass:await hash(v('np')),rol:v('nr')},'Usuario creado');if(S.users.some(x=>x.user===u))return toast('Ese usuario ya existe');S.users.push({user:u,pass:await hash(v('np')),rol:v('nr'),activo:true});save();return render()}
 if(a==='upass'){const p=await askText('Nueva contraseña','Para el usuario '+d.id,'Nueva contraseña','password');if(!p)return;if(SRV)return uop('pass',{user:d.id,pass:await hash(p)},'Clave actualizada');S.users.find(x=>x.user===d.id).pass=await hash(p);save();return toast('Clave actualizada')}
 if(a==='upause'){const u=S.users.find(x=>x.user===d.id);if(u.user===S.me.user)return toast('No podés pausarte a vos mismo');if(SRV)return uop('pause',{user:d.id});u.activo=!u.activo;save();return render()}
 if(a==='udel'){if(d.id===S.me.user)return toast('No podés borrarte a vos mismo');if(!(await ask('Borrar usuario','Se elimina el usuario '+d.id+'.','Borrar',true)))return;if(SRV)return uop('delete',{user:d.id});S.users=S.users.filter(x=>x.user!==d.id);save();return render()}
 if(a==='export'){const H=['legajo','nombre','apellido','dni','contacto','cobro','extra','ingreso','persona a cargo','telefono a cargo','estado'];const K2=['num','nombre','apellido','dni','contacto','cobra','extra','ingreso','aCargo','telACargo','estado'];
  const q=s=>'"'+String(s??'').replace(/"/g,'""')+'"';const OK=[...new Set(S.legs.flatMap(l=>Object.keys(l.otros||{})))];const csv=[H.concat(OK).join(',')].concat(S.legs.map(l=>K2.map(k=>q(l[k])).concat(OK.map(k=>q((l.otros||{})[k]))).join(','))).join('\n');
  const bl=new Blob(['\uFEFF'+csv],{type:'text/csv'});if(NATIVE()){try{await nativeSave('legajos.csv',bl)}catch(e){toast('No se pudo exportar: '+e.message)}return}const a2=document.createElement('a');a2.href=URL.createObjectURL(bl);a2.download='legajos.csv';a2.click();return toast('Exportado')}
}
init();
